import{_ as n,o as i,c as t,ae as r}from"./chunks/framework.BvHJbMD4.js";const u=JSON.parse('{"title":"TEIL 4 – DIE POLITISCHE LIEBESGESCHICHTE","description":"","frontmatter":{},"headers":[],"relativePath":"drehbuch/teil-4-die-politische-liebesgeschichte.md","filePath":"drehbuch/teil-4-die-politische-liebesgeschichte.md"}'),s={name:"drehbuch/teil-4-die-politische-liebesgeschichte.md"};function l(a,e,h,o,d,c){return i(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="teil-4-–-die-politische-liebesgeschichte" tabindex="-1">TEIL 4 – DIE POLITISCHE LIEBESGESCHICHTE <a class="header-anchor" href="#teil-4-–-die-politische-liebesgeschichte" aria-label="Permalink to &quot;TEIL 4 – DIE POLITISCHE LIEBESGESCHICHTE&quot;">​</a></h1><p><strong>INT. OPULENTER PARTEIEMPFANG – ABEND (ARCHIVMATERIAL/REKONSTRUKTION)</strong></p><p>Gedämpftes Gemurmel, Gläserklirren. Elegante Herren und Damen in Abendgarderobe. Politprominenz vermischt sich mit Wirtschaftselite. Kameras blitzen diskret. Schnitt auf Händedrücke, kurze, vertrauliche Gespräche in Ecken. Man lacht viel, aber die Augen sind wachsam.</p><p><strong>NARRATOR (V.O., leicht säuerlich, bemerkend)</strong> Liebe. Ein starkes Wort. Voller Emotionen, Leidenschaft… und manchmal, ja, manchmal auch voller Kalkül. Besonders, wenn sie im Schatten von Parteizentralen und Lobbybüros blüht. Die „politische Liebesgeschichte“ – ein Ballett der Annäherung, bei dem Geld und Einfluss die Hauptrollen spielen. Und die Loyalität… eine Währung ist, die nie ihren Wert verliert.</p><p><strong>INT. STUDIO – INTERVIEW (GRAUER HINTERGRUND, RAUCH)</strong></p><p>PROF. DR. LUDWIG HINTERHUBER (60er, Politikwissenschaftler, mit intellektuellem Bart), zündet sich bedächtig eine Pfeife an.</p><p><strong>PROF. DR. HINTERHUBER</strong> Das ist keine moderne Erfindung. Der Pakt zwischen Geld und Macht ist so alt wie die Demokratie selbst. Nur die Formen… die werden immer raffinierter. Der klassische Bestechungsversuch? Vulgär. Heute spricht man von „Netzwerkpflege“. Von „Expertengesprächen“. Und natürlich: von „Spenden“.</p><p><strong>MONTAGE (SCHNELLE SCHNITTE, AUFPUTSCHENDE MUSIK)</strong></p><p>Tabellen mit Spendeneingängen an Parteien (anonymisiert, aber mit deutlichem ÖVP-Fokus). Grafiken, die Spenden mit politischen Entscheidungen korrelieren (z.B. nach einer Großspende erfolgte eine Gesetzesänderung im Sinne des Spenders). Bilder von lächelnden Politikern mit Industriellen auf Gala-Abenden. Der Schriftzug &quot;Pointillismus des Geldes&quot; erscheint kurz auf dem Bildschirm.</p><p><strong>NARRATOR (V.O.)</strong> Ein Punkt hier, ein Punkt dort. Eine kleine Aufmerksamkeit, ein wohlwollendes Gutachten. Einzeln betrachtet, harmlos. Zusammen… eine ganze Partei in den Armen der Wirtschaft. Eine Liaison, die so diskret wie effektiv ist.</p><p><strong>INT. CAFÉ – TAG (REKONSTRUKTION)</strong></p><p>Eine junge, ambitionierte ÖVP-POLITIKERIN (30er) trifft sich mit einem älteren, erfahrenen LOBBYISTEN (50er) in einem schicken Café. Sie sprechen leise. Der Lobbyist schiebt ihr beiläufig eine Visitenkarte zu. Auf der Rückseite: eine kleine Notiz.</p><p><strong>LOBBYIST</strong> (freundlich, aber bestimmt) Ich bin sicher, Ihre Argumente werden im Ausschuss Gehör finden. Wir teilen schließlich die gleichen… Visionen für unser Land.</p><p><strong>POLITIKERIN</strong> (lächelt charmant) Selbstverständlich. Unsere Visionen sind deckungsgleich, Herr Gruber. Immer.</p><p><strong>NARRATOR (V.O.)</strong> Und so blüht sie, die zarte Pflanze der politischen Romantik. Nährboden: das Klima der Gesetzgebung. Gießwasser: die Quellen der Spenden. Und der Duft, der von ihr ausgeht… nun ja. Den riecht nicht jeder gleich gut.</p><p><strong>EXT. PARLAMENT – TAG (HEUTIGE AUFNAHMEN, SONNIG)</strong></p><p>Das Parlament strahlt in der Sonne. Menschen gehen ein und aus. Alles wirkt normal, demokratisch. Doch die Kamera verweilt kurz auf einem scheinbar unbedeutenden Detail: Ein Transporter, der Blumen liefert, parkt diskret im Hinterhof.</p><p><strong>NARRATOR (V.O.)</strong> Demokratie. Ein komplexes Ökosystem. In dem manche Beziehungen… eben intensiver gepflegt werden als andere. Manchmal mit Blumen. Manchmal mit Millionen. Immer aber… mit einem Lächeln.</p><p><strong>FADE OUT.</strong></p>',19)])])}const p=n(s,[["render",l]]);export{u as __pageData,p as default};
